/**
 * Capture-related type definitions
 * Mirrors backend capture DTOs for type-safe communication
 */

/** Represents a rectangular region for screen capture */
export interface CaptureRegion {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Display/monitor information for capture selection */
export interface DisplayInfo {
  id: string;
  name: string;
  x: number;
  y: number;
  width: number;
  height: number;
  isPrimary: boolean;
  scaleFactor: number;
}

/** Window information for window capture */
export interface WindowInfo {
  id: string;
  title: string;
  processName: string;
  bounds: CaptureRegion;
  isMinimized: boolean;
  isVisible: boolean;
}

/** Capture mode types */
export type CaptureMode = 'screen' | 'window' | 'region' | 'webcam' | 'board';

/** Options for configuring a capture session */
export interface CaptureOptions {
  mode: CaptureMode;
  region?: CaptureRegion;
  displayId?: string;
  windowId?: string;
  frameRate: number;
  captureMouseCursor: boolean;
  captureMouseClicks: boolean;
  maxDuration?: number; // in seconds
  maxFrames?: number;
}

/** Current state of a capture session */
export type CaptureState = 'idle' | 'starting' | 'recording' | 'paused' | 'stopping';

/** Represents an active capture session */
export interface CaptureSession {
  id: string;
  state: CaptureState;
  options: CaptureOptions;
  startedAt?: string;
  frameCount: number;
  duration: number; // in milliseconds
  lastFrameTimestamp?: string;
}

/** Response when starting a capture */
export interface StartCaptureResponse {
  sessionId: string;
  success: boolean;
  error?: string;
}

/** Response when stopping a capture */
export interface StopCaptureResponse {
  sessionId: string;
  frameCount: number;
  duration: number;
  success: boolean;
  error?: string;
}

/**
 * Frame-related type definitions
 * Represents individual frames and their metadata
 */

/** Metadata associated with a single frame */
export interface FrameMetadata {
  index: number;
  timestamp: number; // milliseconds from start
  delay: number; // display delay in milliseconds
  width: number;
  height: number;
  cursorX?: number;
  cursorY?: number;
  mouseClicked?: boolean;
  keyPressed?: string;
}

/** A single frame in a recording/project */
export interface Frame {
  id: string;
  metadata: FrameMetadata;
  imageDataUrl?: string; // Base64 encoded image for preview
  thumbnailUrl?: string; // Smaller preview thumbnail
  filePath?: string; // Path to frame file on disk
  isKeyFrame: boolean;
  isSelected: boolean;
  isDeleted: boolean; // Soft delete for undo support
}

/** Batch of frames for efficient transfer */
export interface FrameBatch {
  sessionId: string;
  startIndex: number;
  frames: Frame[];
  totalFrames: number;
  hasMore: boolean;
}

/** Frame range selection */
export interface FrameRange {
  startIndex: number;
  endIndex: number;
}

/** Frame edit operation types */
export type FrameEditOperation =
  | 'delete'
  | 'duplicate'
  | 'reverse'
  | 'yoyo'
  | 'reduce'
  | 'moveUp'
  | 'moveDown';

/** Request to edit frames */
export interface FrameEditRequest {
  operation: FrameEditOperation;
  frameIds: string[];
  options?: {
    reduceBy?: number; // For reduce operation
    insertPosition?: number; // For move operations
  };
}

/** Result of a frame edit operation */
export interface FrameEditResult {
  success: boolean;
  affectedFrameIds: string[];
  newFrameCount: number;
  error?: string;
}

/**
 * Encoding-related type definitions
 * Configuration and progress for export operations
 */

/** Supported output formats */
export type OutputFormat = 'gif' | 'apng' | 'webp' | 'mp4' | 'webm' | 'avi' | 'png' | 'jpg' | 'psd' | 'stg';

/** GIF encoder options */
export type GifEncoder = 'screentogif' | 'gifski' | 'ffmpeg' | 'system';

/** Video codec options */
export type VideoCodec = 'h264' | 'h265' | 'vp8' | 'vp9' | 'av1';

/** Quantization method for color reduction */
export type QuantizationMethod = 'medianCut' | 'octree' | 'neuQuant' | 'wuQuantizer';

/** Dithering algorithm */
export type DitheringAlgorithm = 'none' | 'floydSteinberg' | 'ordered' | 'atkinson';

/** GIF-specific encoding options */
export interface GifEncodingOptions {
  encoder: GifEncoder;
  colorCount: number; // 2-256
  quantization: QuantizationMethod;
  dithering: DitheringAlgorithm;
  quality: number; // 1-100
  loopCount: number; // 0 = infinite
  enableTransparency: boolean;
  transparencyColor?: string;
  detectUnchangedPixels: boolean;
  paintTransparent: boolean;
}

/** Video-specific encoding options */
export interface VideoEncodingOptions {
  codec: VideoCodec;
  bitrate: number; // in kbps
  quality: number; // CRF value or quality percentage
  preset: 'ultrafast' | 'superfast' | 'veryfast' | 'faster' | 'fast' | 'medium' | 'slow' | 'slower' | 'veryslow';
  pixelFormat: string;
  audioEnabled: boolean;
  audioBitrate?: number;
}

/** APNG-specific encoding options */
export interface ApngEncodingOptions {
  colorDepth: 8 | 16 | 24 | 32;
  compressionLevel: number; // 0-9
  loopCount: number;
  enableTransparency: boolean;
  detectUnchangedPixels: boolean;
}

/** WebP-specific encoding options */
export interface WebpEncodingOptions {
  quality: number; // 0-100
  lossless: boolean;
  loopCount: number;
  method: number; // 0-6, compression method
}

/** Image sequence export options */
export interface ImageSequenceOptions {
  format: 'png' | 'jpg' | 'bmp';
  quality: number; // For JPEG
  namePattern: string; // e.g., "frame_{0:D4}"
  includeTimestamp: boolean;
  zipOutput: boolean;
}

/** Main encoding options union */
export interface EncodingOptions {
  format: OutputFormat;
  outputPath: string;
  width?: number;
  height?: number;
  scale?: number; // 0.1 to 4.0
  frameRate?: number; // Override original frame rate
  trimStart?: number; // Frame index
  trimEnd?: number; // Frame index
  gif?: GifEncodingOptions;
  video?: VideoEncodingOptions;
  apng?: ApngEncodingOptions;
  webp?: WebpEncodingOptions;
  imageSequence?: ImageSequenceOptions;
}

/** Encoding job state */
export type EncodingState = 'queued' | 'preparing' | 'encoding' | 'optimizing' | 'completed' | 'failed' | 'cancelled';

/** Progress information for an encoding job */
export interface EncodingProgress {
  jobId: string;
  state: EncodingState;
  progress: number; // 0-100
  currentFrame: number;
  totalFrames: number;
  stage: string; // Human-readable stage description
  estimatedTimeRemaining?: number; // milliseconds
  outputFileSize?: number; // bytes
  error?: string;
  startedAt: string;
  completedAt?: string;
}

/** Request to start encoding */
export interface StartEncodingRequest {
  projectId: string;
  options: EncodingOptions;
}

/** Response from starting an encoding job */
export interface StartEncodingResponse {
  jobId: string;
  success: boolean;
  error?: string;
}

/** Response when encoding completes */
export interface EncodingCompleteResponse {
  jobId: string;
  outputPath: string;
  fileSize: number;
  duration: number; // encoding duration in ms
  success: boolean;
  error?: string;
}

