/**
 * Recorder Store
 * Manages recording state, capture configuration, and session data
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type {
  CaptureRegion,
  CaptureOptions,
  CaptureState,
  CaptureSession,
  DisplayInfo,
  WindowInfo,
  CaptureMode,
} from '../api/types';

interface RecorderState {
  // Recording state
  captureState: CaptureState;
  currentSession: CaptureSession | null;
  isPaused: boolean;

  // Capture configuration
  captureMode: CaptureMode;
  selectedRegion: CaptureRegion | null;
  selectedDisplayId: string | null;
  selectedWindowId: string | null;
  frameRate: number;
  captureMouseCursor: boolean;
  captureMouseClicks: boolean;
  maxDuration: number | null; // seconds
  maxFrames: number | null;

  // Available sources
  availableDisplays: DisplayInfo[];
  availableWindows: WindowInfo[];

  // Stats during recording
  frameCount: number;
  recordingDuration: number; // milliseconds
  estimatedFileSize: number; // bytes

  // UI state
  isSelectingRegion: boolean;
  showPreview: boolean;
  previewScale: number;

  // Error state
  error: string | null;
}

interface RecorderActions {
  // State setters
  setCaptureState: (state: CaptureState) => void;
  setCurrentSession: (session: CaptureSession | null) => void;
  setIsPaused: (paused: boolean) => void;

  // Configuration setters
  setCaptureMode: (mode: CaptureMode) => void;
  setSelectedRegion: (region: CaptureRegion | null) => void;
  setSelectedDisplayId: (displayId: string | null) => void;
  setSelectedWindowId: (windowId: string | null) => void;
  setFrameRate: (rate: number) => void;
  setCaptureMouseCursor: (capture: boolean) => void;
  setCaptureMouseClicks: (capture: boolean) => void;
  setMaxDuration: (duration: number | null) => void;
  setMaxFrames: (frames: number | null) => void;

  // Source management
  setAvailableDisplays: (displays: DisplayInfo[]) => void;
  setAvailableWindows: (windows: WindowInfo[]) => void;
  refreshSources: () => void;

  // Stats updates
  incrementFrameCount: () => void;
  setFrameCount: (count: number) => void;
  setRecordingDuration: (duration: number) => void;
  setEstimatedFileSize: (size: number) => void;

  // UI state
  setIsSelectingRegion: (selecting: boolean) => void;
  setShowPreview: (show: boolean) => void;
  setPreviewScale: (scale: number) => void;

  // Error handling
  setError: (error: string | null) => void;
  clearError: () => void;

  // Computed getters
  getCaptureOptions: () => CaptureOptions;
  canStartRecording: () => boolean;

  // Reset
  reset: () => void;
  resetSession: () => void;
}

const initialState: RecorderState = {
  captureState: 'idle',
  currentSession: null,
  isPaused: false,
  captureMode: 'region',
  selectedRegion: null,
  selectedDisplayId: null,
  selectedWindowId: null,
  frameRate: 15,
  captureMouseCursor: true,
  captureMouseClicks: false,
  maxDuration: null,
  maxFrames: null,
  availableDisplays: [],
  availableWindows: [],
  frameCount: 0,
  recordingDuration: 0,
  estimatedFileSize: 0,
  isSelectingRegion: false,
  showPreview: true,
  previewScale: 1,
  error: null,
};

export const useRecorderStore = create<RecorderState & RecorderActions>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // State setters
    setCaptureState: (captureState) => set({ captureState }),
    setCurrentSession: (currentSession) => set({ currentSession }),
    setIsPaused: (isPaused) => set({ isPaused }),

    // Configuration setters
    setCaptureMode: (captureMode) => set({ captureMode }),
    setSelectedRegion: (selectedRegion) => set({ selectedRegion }),
    setSelectedDisplayId: (selectedDisplayId) => set({ selectedDisplayId }),
    setSelectedWindowId: (selectedWindowId) => set({ selectedWindowId }),
    setFrameRate: (frameRate) => set({ frameRate: Math.min(Math.max(frameRate, 1), 60) }),
    setCaptureMouseCursor: (captureMouseCursor) => set({ captureMouseCursor }),
    setCaptureMouseClicks: (captureMouseClicks) => set({ captureMouseClicks }),
    setMaxDuration: (maxDuration) => set({ maxDuration }),
    setMaxFrames: (maxFrames) => set({ maxFrames }),

    // Source management
    setAvailableDisplays: (availableDisplays) => set({ availableDisplays }),
    setAvailableWindows: (availableWindows) => set({ availableWindows }),
    refreshSources: () => {
      // This will be called by components that have access to the API
      // The actual fetching happens in the component/service layer
    },

    // Stats updates
    incrementFrameCount: () => set((state) => ({ frameCount: state.frameCount + 1 })),
    setFrameCount: (frameCount) => set({ frameCount }),
    setRecordingDuration: (recordingDuration) => set({ recordingDuration }),
    setEstimatedFileSize: (estimatedFileSize) => set({ estimatedFileSize }),

    // UI state
    setIsSelectingRegion: (isSelectingRegion) => set({ isSelectingRegion }),
    setShowPreview: (showPreview) => set({ showPreview }),
    setPreviewScale: (previewScale) => set({ previewScale }),

    // Error handling
    setError: (error) => set({ error }),
    clearError: () => set({ error: null }),

    // Computed getters
    getCaptureOptions: (): CaptureOptions => {
      const state = get();
      return {
        mode: state.captureMode,
        region: state.selectedRegion ?? undefined,
        displayId: state.selectedDisplayId ?? undefined,
        windowId: state.selectedWindowId ?? undefined,
        frameRate: state.frameRate,
        captureMouseCursor: state.captureMouseCursor,
        captureMouseClicks: state.captureMouseClicks,
        maxDuration: state.maxDuration ?? undefined,
        maxFrames: state.maxFrames ?? undefined,
      };
    },

    canStartRecording: (): boolean => {
      const state = get();
      if (state.captureState !== 'idle') return false;

      switch (state.captureMode) {
        case 'region':
          return state.selectedRegion !== null;
        case 'screen':
          return state.selectedDisplayId !== null;
        case 'window':
          return state.selectedWindowId !== null;
        case 'webcam':
        case 'board':
          return true;
        default:
          return false;
      }
    },

    // Reset
    reset: () => set(initialState),
    resetSession: () =>
      set({
        currentSession: null,
        frameCount: 0,
        recordingDuration: 0,
        estimatedFileSize: 0,
        captureState: 'idle',
        isPaused: false,
        error: null,
      }),
  }))
);

// Selector hooks for common selections
export const selectCaptureState = (state: RecorderState & RecorderActions) => state.captureState;
export const selectIsRecording = (state: RecorderState & RecorderActions) =>
  state.captureState === 'recording';
export const selectCaptureOptions = (state: RecorderState & RecorderActions) =>
  state.getCaptureOptions();

/**
 * Editor Store
 * Manages timeline, selection, playback, and editing state
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type { Frame, FrameRange } from '../api/types';

/** Playback state */
export type PlaybackState = 'stopped' | 'playing' | 'paused';

/** Selection mode for frames */
export type SelectionMode = 'single' | 'range' | 'multi';

/** Tool types available in editor */
export type EditorTool =
  | 'select'
  | 'crop'
  | 'resize'
  | 'flip'
  | 'rotate'
  | 'text'
  | 'drawing'
  | 'shapes'
  | 'blur'
  | 'watermark'
  | 'border'
  | 'shadow'
  | 'keystrokes'
  | 'cursor'
  | 'progress';

/** Zoom level preset */
export type ZoomPreset = 'fit' | 'fill' | '25' | '50' | '75' | '100' | '150' | '200' | '400';

interface EditorState {
  // Frame selection
  selectedFrameIds: string[];
  selectionMode: SelectionMode;
  selectionRange: FrameRange | null;
  lastSelectedFrameId: string | null;

  // Playback
  playbackState: PlaybackState;
  currentFrameIndex: number;
  playbackSpeed: number; // 0.25 to 4.0
  isLooping: boolean;

  // Timeline
  timelineZoom: number; // 0.5 to 4.0
  timelineScrollPosition: number;
  thumbnailSize: 'small' | 'medium' | 'large';
  showFrameNumbers: boolean;
  showFrameDelays: boolean;

  // Editor canvas
  canvasZoom: number;
  canvasZoomPreset: ZoomPreset;
  canvasPanX: number;
  canvasPanY: number;
  showGrid: boolean;
  gridSize: number;
  snapToGrid: boolean;

  // Current tool
  currentTool: EditorTool;
  toolOptions: Record<string, unknown>;

  // Clipboard
  clipboardFrameIds: string[];
  clipboardOperation: 'copy' | 'cut' | null;

  // Undo/Redo
  canUndo: boolean;
  canRedo: boolean;
  historyIndex: number;

  // UI state
  isSidebarCollapsed: boolean;
  isTimelineCollapsed: boolean;
  activePanel: 'frames' | 'effects' | 'export' | 'settings';

  // Preview
  showOnionSkin: boolean;
  onionSkinFramesBefore: number;
  onionSkinFramesAfter: number;
  onionSkinOpacity: number;
}

interface EditorActions {
  // Frame selection
  selectFrame: (frameId: string, addToSelection?: boolean) => void;
  selectFrames: (frameIds: string[]) => void;
  selectFrameRange: (startId: string, endId: string) => void;
  selectAllFrames: (frameIds: string[]) => void;
  deselectFrame: (frameId: string) => void;
  clearSelection: () => void;
  setSelectionMode: (mode: SelectionMode) => void;
  invertSelection: (allFrameIds: string[]) => void;

  // Playback
  play: () => void;
  pause: () => void;
  stop: () => void;
  togglePlayback: () => void;
  setCurrentFrameIndex: (index: number) => void;
  nextFrame: () => void;
  previousFrame: () => void;
  goToFirstFrame: () => void;
  goToLastFrame: (totalFrames: number) => void;
  setPlaybackSpeed: (speed: number) => void;
  setIsLooping: (looping: boolean) => void;

  // Timeline
  setTimelineZoom: (zoom: number) => void;
  setTimelineScrollPosition: (position: number) => void;
  setThumbnailSize: (size: 'small' | 'medium' | 'large') => void;
  setShowFrameNumbers: (show: boolean) => void;
  setShowFrameDelays: (show: boolean) => void;

  // Canvas
  setCanvasZoom: (zoom: number) => void;
  setCanvasZoomPreset: (preset: ZoomPreset) => void;
  zoomIn: () => void;
  zoomOut: () => void;
  fitToWindow: () => void;
  resetZoom: () => void;
  setCanvasPan: (x: number, y: number) => void;
  setShowGrid: (show: boolean) => void;
  setGridSize: (size: number) => void;
  setSnapToGrid: (snap: boolean) => void;

  // Tools
  setCurrentTool: (tool: EditorTool) => void;
  setToolOption: (key: string, value: unknown) => void;
  clearToolOptions: () => void;

  // Clipboard
  copyFrames: (frameIds: string[]) => void;
  cutFrames: (frameIds: string[]) => void;
  clearClipboard: () => void;
  hasClipboardContent: () => boolean;

  // History
  setCanUndo: (canUndo: boolean) => void;
  setCanRedo: (canRedo: boolean) => void;
  setHistoryIndex: (index: number) => void;

  // UI
  toggleSidebar: () => void;
  toggleTimeline: () => void;
  setActivePanel: (panel: 'frames' | 'effects' | 'export' | 'settings') => void;

  // Onion skin
  setShowOnionSkin: (show: boolean) => void;
  setOnionSkinFramesBefore: (frames: number) => void;
  setOnionSkinFramesAfter: (frames: number) => void;
  setOnionSkinOpacity: (opacity: number) => void;

  // Reset
  reset: () => void;
}

const initialState: EditorState = {
  selectedFrameIds: [],
  selectionMode: 'single',
  selectionRange: null,
  lastSelectedFrameId: null,
  playbackState: 'stopped',
  currentFrameIndex: 0,
  playbackSpeed: 1.0,
  isLooping: true,
  timelineZoom: 1.0,
  timelineScrollPosition: 0,
  thumbnailSize: 'medium',
  showFrameNumbers: true,
  showFrameDelays: false,
  canvasZoom: 1.0,
  canvasZoomPreset: '100',
  canvasPanX: 0,
  canvasPanY: 0,
  showGrid: false,
  gridSize: 16,
  snapToGrid: false,
  currentTool: 'select',
  toolOptions: {},
  clipboardFrameIds: [],
  clipboardOperation: null,
  canUndo: false,
  canRedo: false,
  historyIndex: -1,
  isSidebarCollapsed: false,
  isTimelineCollapsed: false,
  activePanel: 'frames',
  showOnionSkin: false,
  onionSkinFramesBefore: 1,
  onionSkinFramesAfter: 1,
  onionSkinOpacity: 0.3,
};

const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0];

export const useEditorStore = create<EditorState & EditorActions>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // Frame selection
    selectFrame: (frameId, addToSelection = false) => {
      set((state) => {
        if (addToSelection) {
          const newSelection = state.selectedFrameIds.includes(frameId)
            ? state.selectedFrameIds.filter((id) => id !== frameId)
            : [...state.selectedFrameIds, frameId];
          return { selectedFrameIds: newSelection, lastSelectedFrameId: frameId };
        }
        return { selectedFrameIds: [frameId], lastSelectedFrameId: frameId };
      });
    },

    selectFrames: (frameIds) => set({ selectedFrameIds: frameIds }),

    selectFrameRange: (startId, endId) => {
      set({ selectionRange: { startIndex: parseInt(startId), endIndex: parseInt(endId) } });
    },

    selectAllFrames: (frameIds) => set({ selectedFrameIds: frameIds }),

    deselectFrame: (frameId) =>
      set((state) => ({
        selectedFrameIds: state.selectedFrameIds.filter((id) => id !== frameId),
      })),

    clearSelection: () =>
      set({ selectedFrameIds: [], selectionRange: null, lastSelectedFrameId: null }),

    setSelectionMode: (selectionMode) => set({ selectionMode }),

    invertSelection: (allFrameIds) =>
      set((state) => ({
        selectedFrameIds: allFrameIds.filter((id) => !state.selectedFrameIds.includes(id)),
      })),

    // Playback
    play: () => set({ playbackState: 'playing' }),
    pause: () => set({ playbackState: 'paused' }),
    stop: () => set({ playbackState: 'stopped', currentFrameIndex: 0 }),

    togglePlayback: () => {
      const { playbackState } = get();
      if (playbackState === 'playing') {
        set({ playbackState: 'paused' });
      } else {
        set({ playbackState: 'playing' });
      }
    },

    setCurrentFrameIndex: (currentFrameIndex) => set({ currentFrameIndex }),

    nextFrame: () =>
      set((state) => ({ currentFrameIndex: state.currentFrameIndex + 1 })),

    previousFrame: () =>
      set((state) => ({
        currentFrameIndex: Math.max(0, state.currentFrameIndex - 1),
      })),

    goToFirstFrame: () => set({ currentFrameIndex: 0 }),

    goToLastFrame: (totalFrames) =>
      set({ currentFrameIndex: Math.max(0, totalFrames - 1) }),

    setPlaybackSpeed: (playbackSpeed) =>
      set({ playbackSpeed: Math.min(Math.max(playbackSpeed, 0.25), 4.0) }),

    setIsLooping: (isLooping) => set({ isLooping }),

    // Timeline
    setTimelineZoom: (timelineZoom) =>
      set({ timelineZoom: Math.min(Math.max(timelineZoom, 0.5), 4.0) }),

    setTimelineScrollPosition: (timelineScrollPosition) => set({ timelineScrollPosition }),

    setThumbnailSize: (thumbnailSize) => set({ thumbnailSize }),
    setShowFrameNumbers: (showFrameNumbers) => set({ showFrameNumbers }),
    setShowFrameDelays: (showFrameDelays) => set({ showFrameDelays }),

    // Canvas
    setCanvasZoom: (canvasZoom) => set({ canvasZoom, canvasZoomPreset: 'fit' }),

    setCanvasZoomPreset: (preset) => {
      const zoomMap: Record<ZoomPreset, number | null> = {
        fit: null,
        fill: null,
        '25': 0.25,
        '50': 0.5,
        '75': 0.75,
        '100': 1.0,
        '150': 1.5,
        '200': 2.0,
        '400': 4.0,
      };
      const zoom = zoomMap[preset];
      if (zoom !== null) {
        set({ canvasZoom: zoom, canvasZoomPreset: preset });
      } else {
        set({ canvasZoomPreset: preset });
      }
    },

    zoomIn: () => {
      const { canvasZoom } = get();
      const nextIndex = ZOOM_LEVELS.findIndex((z) => z > canvasZoom);
      if (nextIndex !== -1) {
        set({ canvasZoom: ZOOM_LEVELS[nextIndex] });
      }
    },

    zoomOut: () => {
      const { canvasZoom } = get();
      const prevIndex = [...ZOOM_LEVELS].reverse().findIndex((z) => z < canvasZoom);
      if (prevIndex !== -1) {
        set({ canvasZoom: ZOOM_LEVELS[ZOOM_LEVELS.length - 1 - prevIndex] });
      }
    },

    fitToWindow: () => set({ canvasZoomPreset: 'fit' }),
    resetZoom: () => set({ canvasZoom: 1.0, canvasZoomPreset: '100', canvasPanX: 0, canvasPanY: 0 }),

    setCanvasPan: (canvasPanX, canvasPanY) => set({ canvasPanX, canvasPanY }),
    setShowGrid: (showGrid) => set({ showGrid }),
    setGridSize: (gridSize) => set({ gridSize }),
    setSnapToGrid: (snapToGrid) => set({ snapToGrid }),

    // Tools
    setCurrentTool: (currentTool) => set({ currentTool }),
    setToolOption: (key, value) =>
      set((state) => ({ toolOptions: { ...state.toolOptions, [key]: value } })),
    clearToolOptions: () => set({ toolOptions: {} }),

    // Clipboard
    copyFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'copy' }),
    cutFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'cut' }),
    clearClipboard: () => set({ clipboardFrameIds: [], clipboardOperation: null }),
    hasClipboardContent: () => get().clipboardFrameIds.length > 0,

    // History
    setCanUndo: (canUndo) => set({ canUndo }),
    setCanRedo: (canRedo) => set({ canRedo }),
    setHistoryIndex: (historyIndex) => set({ historyIndex }),

    // UI
    toggleSidebar: () => set((state) => ({ isSidebarCollapsed: !state.isSidebarCollapsed })),
    toggleTimeline: () => set((state) => ({ isTimelineCollapsed: !state.isTimelineCollapsed })),
    setActivePanel: (activePanel) => set({ activePanel }),

    // Onion skin
    setShowOnionSkin: (showOnionSkin) => set({ showOnionSkin }),
    setOnionSkinFramesBefore: (onionSkinFramesBefore) => set({ onionSkinFramesBefore }),
    setOnionSkinFramesAfter: (onionSkinFramesAfter) => set({ onionSkinFramesAfter }),
    setOnionSkinOpacity: (onionSkinOpacity) => set({ onionSkinOpacity }),

    // Reset
    reset: () => set(initialState),
  }))
);

// Selector hooks
export const selectIsPlaying = (state: EditorState) => state.playbackState === 'playing';
export const selectSelectedFrameCount = (state: EditorState) => state.selectedFrameIds.length;
export const selectHasSelection = (state: EditorState) => state.selectedFrameIds.length > 0;

/**
 * Project Store
 * Manages project data, frames, tracks, and file operations
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type {
  Project,
  ProjectMetadata,
  ProjectFileInfo,
  Frame,
  Track,
  Sequence,
  HistoryEntry,
} from '../api/types';

interface ProjectState {
  // Current project
  currentProject: Project | null;
  isLoading: boolean;
  isSaving: boolean;

  // Frames (main data)
  frames: Frame[];
  totalFrameCount: number;

  // Sequences and tracks
  sequences: Sequence[];
  activeSequenceId: string | null;

  // File state
  filePath: string | null;
  isDirty: boolean;
  lastSavedAt: string | null;
  autoSaveEnabled: boolean;
  autoSaveInterval: number; // milliseconds

  // Recent projects
  recentProjects: ProjectFileInfo[];
  maxRecentProjects: number;

  // History (undo/redo)
  history: HistoryEntry[];
  historyIndex: number;
  maxHistorySize: number;

  // Error state
  error: string | null;
  warnings: string[];
}

interface ProjectActions {
  // Project lifecycle
  createProject: (metadata: ProjectMetadata, width: number, height: number, frameRate: number) => void;
  loadProject: (project: Project) => void;
  closeProject: () => void;
  setIsLoading: (loading: boolean) => void;
  setIsSaving: (saving: boolean) => void;

  // Project metadata
  updateMetadata: (metadata: Partial<ProjectMetadata>) => void;
  setFilePath: (path: string | null) => void;
  markDirty: () => void;
  markClean: () => void;
  setLastSavedAt: (timestamp: string) => void;

  // Frame management
  setFrames: (frames: Frame[]) => void;
  addFrame: (frame: Frame, index?: number) => void;
  addFrames: (frames: Frame[], index?: number) => void;
  updateFrame: (frameId: string, updates: Partial<Frame>) => void;
  updateFrames: (updates: { id: string; changes: Partial<Frame> }[]) => void;
  removeFrame: (frameId: string) => void;
  removeFrames: (frameIds: string[]) => void;
  reorderFrames: (fromIndex: number, toIndex: number) => void;
  duplicateFrames: (frameIds: string[], insertAfter?: string) => void;

  // Frame delay management
  setFrameDelay: (frameId: string, delay: number) => void;
  setFramesDelay: (frameIds: string[], delay: number) => void;
  scaleDelays: (factor: number) => void;

  // Sequence management
  setSequences: (sequences: Sequence[]) => void;
  addSequence: (sequence: Sequence) => void;
  removeSequence: (sequenceId: string) => void;
  setActiveSequenceId: (sequenceId: string | null) => void;

  // Track management
  addTrack: (sequenceId: string, track: Track) => void;
  removeTrack: (sequenceId: string, trackId: string) => void;
  updateTrack: (sequenceId: string, trackId: string, updates: Partial<Track>) => void;

  // Recent projects
  addRecentProject: (projectInfo: ProjectFileInfo) => void;
  removeRecentProject: (path: string) => void;
  clearRecentProjects: () => void;

  // Auto-save
  setAutoSaveEnabled: (enabled: boolean) => void;
  setAutoSaveInterval: (interval: number) => void;

  // History (undo/redo)
  pushHistory: (entry: HistoryEntry) => void;
  undo: () => HistoryEntry | null;
  redo: () => HistoryEntry | null;
  clearHistory: () => void;
  canUndo: () => boolean;
  canRedo: () => boolean;

  // Error handling
  setError: (error: string | null) => void;
  addWarning: (warning: string) => void;
  clearWarnings: () => void;

  // Computed values
  getTotalDuration: () => number;
  getFrameById: (frameId: string) => Frame | undefined;
  getFrameByIndex: (index: number) => Frame | undefined;
  getActiveSequence: () => Sequence | undefined;

  // Reset
  reset: () => void;
}

const initialState: ProjectState = {
  currentProject: null,
  isLoading: false,
  isSaving: false,
  frames: [],
  totalFrameCount: 0,
  sequences: [],
  activeSequenceId: null,
  filePath: null,
  isDirty: false,
  lastSavedAt: null,
  autoSaveEnabled: true,
  autoSaveInterval: 60000, // 1 minute
  recentProjects: [],
  maxRecentProjects: 10,
  history: [],
  historyIndex: -1,
  maxHistorySize: 100,
  error: null,
  warnings: [],
};

export const useProjectStore = create<ProjectState & ProjectActions>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // Project lifecycle
    createProject: (metadata, width, height, frameRate) => {
      const project: Project = {
        id: crypto.randomUUID(),
        metadata: {
          ...metadata,
          createdAt: new Date().toISOString(),
          modifiedAt: new Date().toISOString(),
          version: '1.0.0',
        },
        sequences: [],
        frames: [],
        originalWidth: width,
        originalHeight: height,
        originalFrameRate: frameRate,
        totalDuration: 0,
        isDirty: false,
        autoSaveEnabled: true,
      };
      set({
        currentProject: project,
        frames: [],
        totalFrameCount: 0,
        sequences: [],
        isDirty: false,
        filePath: null,
        error: null,
        warnings: [],
      });
    },

    loadProject: (project) => {
      set({
        currentProject: project,
        frames: project.frames,
        totalFrameCount: project.frames.length,
        sequences: project.sequences,
        activeSequenceId: project.sequences[0]?.id ?? null,
        filePath: project.filePath ?? null,
        isDirty: false,
        lastSavedAt: project.lastSavedAt ?? null,
        error: null,
        warnings: [],
        history: [],
        historyIndex: -1,
      });
    },

    closeProject: () => {
      set({
        currentProject: null,
        frames: [],
        totalFrameCount: 0,
        sequences: [],
        activeSequenceId: null,
        filePath: null,
        isDirty: false,
        lastSavedAt: null,
        history: [],
        historyIndex: -1,
        error: null,
        warnings: [],
      });
    },

    setIsLoading: (isLoading) => set({ isLoading }),
    setIsSaving: (isSaving) => set({ isSaving }),

    // Project metadata
    updateMetadata: (metadata) =>
      set((state) => ({
        currentProject: state.currentProject
          ? {
              ...state.currentProject,
              metadata: {
                ...state.currentProject.metadata,
                ...metadata,
                modifiedAt: new Date().toISOString(),
              },
            }
          : null,
        isDirty: true,
      })),

    setFilePath: (filePath) => set({ filePath }),
    markDirty: () => set({ isDirty: true }),
    markClean: () => set({ isDirty: false }),
    setLastSavedAt: (lastSavedAt) => set({ lastSavedAt, isDirty: false }),

    // Frame management
    setFrames: (frames) => set({ frames, totalFrameCount: frames.length, isDirty: true }),

    addFrame: (frame, index) =>
      set((state) => {
        const newFrames = [...state.frames];
        if (index !== undefined) {
          newFrames.splice(index, 0, frame);
        } else {
          newFrames.push(frame);
        }
        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
      }),

    addFrames: (frames, index) =>
      set((state) => {
        const newFrames = [...state.frames];
        if (index !== undefined) {
          newFrames.splice(index, 0, ...frames);
        } else {
          newFrames.push(...frames);
        }
        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
      }),

    updateFrame: (frameId, updates) =>
      set((state) => ({
        frames: state.frames.map((f) => (f.id === frameId ? { ...f, ...updates } : f)),
        isDirty: true,
      })),

    updateFrames: (updates) =>
      set((state) => ({
        frames: state.frames.map((f) => {
          const update = updates.find((u) => u.id === f.id);
          return update ? { ...f, ...update.changes } : f;
        }),
        isDirty: true,
      })),

    removeFrame: (frameId) =>
      set((state) => {
        const newFrames = state.frames.filter((f) => f.id !== frameId);
        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
      }),

    removeFrames: (frameIds) =>
      set((state) => {
        const newFrames = state.frames.filter((f) => !frameIds.includes(f.id));
        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
      }),

    reorderFrames: (fromIndex, toIndex) =>
      set((state) => {
        const newFrames = [...state.frames];
        const [removed] = newFrames.splice(fromIndex, 1);
        newFrames.splice(toIndex, 0, removed);
        return { frames: newFrames, isDirty: true };
      }),

    duplicateFrames: (frameIds, insertAfter) =>
      set((state) => {
        const framesToDupe = state.frames.filter((f) => frameIds.includes(f.id));
        const duplicates = framesToDupe.map((f) => ({
          ...f,
          id: crypto.randomUUID(),
          isSelected: false,
        }));

        let insertIndex = state.frames.length;
        if (insertAfter) {
          const afterIndex = state.frames.findIndex((f) => f.id === insertAfter);
          if (afterIndex !== -1) {
            insertIndex = afterIndex + 1;
          }
        }

        const newFrames = [...state.frames];
        newFrames.splice(insertIndex, 0, ...duplicates);
        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
      }),

    // Frame delay management
    setFrameDelay: (frameId, delay) =>
      set((state) => ({
        frames: state.frames.map((f) =>
          f.id === frameId ? { ...f, metadata: { ...f.metadata, delay } } : f
        ),
        isDirty: true,
      })),

    setFramesDelay: (frameIds, delay) =>
      set((state) => ({
        frames: state.frames.map((f) =>
          frameIds.includes(f.id) ? { ...f, metadata: { ...f.metadata, delay } } : f
        ),
        isDirty: true,
      })),

    scaleDelays: (factor) =>
      set((state) => ({
        frames: state.frames.map((f) => ({
          ...f,
          metadata: { ...f.metadata, delay: Math.round(f.metadata.delay * factor) },
        })),
        isDirty: true,
      })),

    // Sequence management
    setSequences: (sequences) => set({ sequences, isDirty: true }),
    addSequence: (sequence) =>
      set((state) => ({ sequences: [...state.sequences, sequence], isDirty: true })),
    removeSequence: (sequenceId) =>
      set((state) => ({
        sequences: state.sequences.filter((s) => s.id !== sequenceId),
        isDirty: true,
      })),
    setActiveSequenceId: (activeSequenceId) => set({ activeSequenceId }),

    // Track management
    addTrack: (sequenceId, track) =>
      set((state) => ({
        sequences: state.sequences.map((s) =>
          s.id === sequenceId ? { ...s, tracks: [...s.tracks, track] } : s
        ),
        isDirty: true,
      })),

    removeTrack: (sequenceId, trackId) =>
      set((state) => ({
        sequences: state.sequences.map((s) =>
          s.id === sequenceId ? { ...s, tracks: s.tracks.filter((t) => t.id !== trackId) } : s
        ),
        isDirty: true,
      })),

    updateTrack: (sequenceId, trackId, updates) =>
      set((state) => ({
        sequences: state.sequences.map((s) =>
          s.id === sequenceId
            ? { ...s, tracks: s.tracks.map((t) => (t.id === trackId ? { ...t, ...updates } : t)) }
            : s
        ),
        isDirty: true,
      })),

    // Recent projects
    addRecentProject: (projectInfo) =>
      set((state) => {
        const filtered = state.recentProjects.filter((p) => p.path !== projectInfo.path);
        const newRecent = [projectInfo, ...filtered].slice(0, state.maxRecentProjects);
        return { recentProjects: newRecent };
      }),

    removeRecentProject: (path) =>
      set((state) => ({
        recentProjects: state.recentProjects.filter((p) => p.path !== path),
      })),

    clearRecentProjects: () => set({ recentProjects: [] }),

    // Auto-save
    setAutoSaveEnabled: (autoSaveEnabled) => set({ autoSaveEnabled }),
    setAutoSaveInterval: (autoSaveInterval) => set({ autoSaveInterval }),

    // History (undo/redo)
    pushHistory: (entry) =>
      set((state) => {
        // Remove any redo history
        const newHistory = state.history.slice(0, state.historyIndex + 1);
        newHistory.push(entry);
        // Trim to max size
        if (newHistory.length > state.maxHistorySize) {
          newHistory.shift();
        }
        return { history: newHistory, historyIndex: newHistory.length - 1 };
      }),

    undo: () => {
      const { history, historyIndex } = get();
      if (historyIndex >= 0) {
        set({ historyIndex: historyIndex - 1 });
        return history[historyIndex];
      }
      return null;
    },

    redo: () => {
      const { history, historyIndex } = get();
      if (historyIndex < history.length - 1) {
        set({ historyIndex: historyIndex + 1 });
        return history[historyIndex + 1];
      }
      return null;
    },

    clearHistory: () => set({ history: [], historyIndex: -1 }),
    canUndo: () => get().historyIndex >= 0,
    canRedo: () => get().historyIndex < get().history.length - 1,

    // Error handling
    setError: (error) => set({ error }),
    addWarning: (warning) => set((state) => ({ warnings: [...state.warnings, warning] })),
    clearWarnings: () => set({ warnings: [] }),

    // Computed values
    getTotalDuration: () => {
      const { frames } = get();
      return frames.reduce((sum, f) => sum + f.metadata.delay, 0);
    },

    getFrameById: (frameId) => get().frames.find((f) => f.id === frameId),
    getFrameByIndex: (index) => get().frames[index],
    getActiveSequence: () => {
      const { sequences, activeSequenceId } = get();
      return sequences.find((s) => s.id === activeSequenceId);
    },

    // Reset
    reset: () => set(initialState),
  }))
);

// Selector hooks
export const selectHasProject = (state: ProjectState) => state.currentProject !== null;
export const selectIsDirty = (state: ProjectState) => state.isDirty;
export const selectFrameCount = (state: ProjectState) => state.totalFrameCount;
export const selectProjectTitle = (state: ProjectState) =>
  state.currentProject?.metadata.title ?? 'Untitled';

