/**
 * Capture Client
 * API client for screen capture operations
 */

import { invoke } from '@tauri-apps/api/core';
import type {
  CaptureOptions,
  CaptureSession,
  StartCaptureResponse,
  StopCaptureResponse,
  DisplayInfo,
  WindowInfo,
  CaptureRegion,
} from '../types';

const BACKEND_BASE_URL = 'http://localhost:5001';

/**
 * Get list of available displays/monitors
 */
export async function getDisplays(): Promise<DisplayInfo[]> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/displays`);
  if (!response.ok) {
    throw new Error(`Failed to get displays: ${response.status}`);
  }
  return response.json();
}

/**
 * Get list of available windows for capture
 */
export async function getWindows(): Promise<WindowInfo[]> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/windows`);
  if (!response.ok) {
    throw new Error(`Failed to get windows: ${response.status}`);
  }
  return response.json();
}

/**
 * Start a capture session with given options
 */
export async function startCapture(options: CaptureOptions): Promise<StartCaptureResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(options),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to start capture: ${error}`);
  }
  return response.json();
}

/**
 * Stop the current capture session
 */
export async function stopCapture(sessionId: string): Promise<StopCaptureResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/stop`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId }),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to stop capture: ${error}`);
  }
  return response.json();
}

/**
 * Pause the current capture session
 */
export async function pauseCapture(sessionId: string): Promise<void> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/pause`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId }),
  });
  if (!response.ok) {
    throw new Error(`Failed to pause capture: ${response.status}`);
  }
}

/**
 * Resume a paused capture session
 */
export async function resumeCapture(sessionId: string): Promise<void> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/resume`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId }),
  });
  if (!response.ok) {
    throw new Error(`Failed to resume capture: ${response.status}`);
  }
}

/**
 * Discard the current capture session
 */
export async function discardCapture(sessionId: string): Promise<void> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/discard`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId }),
  });
  if (!response.ok) {
    throw new Error(`Failed to discard capture: ${response.status}`);
  }
}

/**
 * Get current capture session status
 */
export async function getCaptureStatus(sessionId: string): Promise<CaptureSession> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/status/${sessionId}`);
  if (!response.ok) {
    throw new Error(`Failed to get capture status: ${response.status}`);
  }
  return response.json();
}

/**
 * Get frames from a capture session
 */
export async function getCaptureFrames(
  sessionId: string,
  startIndex: number = 0,
  count: number = 50
): Promise<{ frames: unknown[]; total: number; hasMore: boolean }> {
  const response = await fetch(
    `${BACKEND_BASE_URL}/api/capture/frames/${sessionId}?start=${startIndex}&count=${count}`
  );
  if (!response.ok) {
    throw new Error(`Failed to get capture frames: ${response.status}`);
  }
  return response.json();
}

/**
 * Get a specific frame by index
 */
export async function getCaptureFrame(
  sessionId: string,
  frameIndex: number
): Promise<{ imageData: string; metadata: unknown }> {
  const response = await fetch(
    `${BACKEND_BASE_URL}/api/capture/frame/${sessionId}/${frameIndex}`
  );
  if (!response.ok) {
    throw new Error(`Failed to get frame: ${response.status}`);
  }
  return response.json();
}

/**
 * Show region selector overlay via Tauri
 */
export async function showRegionSelector(): Promise<CaptureRegion | null> {
  return invoke<CaptureRegion | null>('show_region_selector');
}

/**
 * Hide region selector overlay via Tauri
 */
export async function hideRegionSelector(): Promise<void> {
  return invoke<void>('hide_region_selector');
}

/**
 * Take a single screenshot
 */
export async function takeScreenshot(
  region?: CaptureRegion
): Promise<{ imageData: string; width: number; height: number }> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/capture/screenshot`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ region }),
  });
  if (!response.ok) {
    throw new Error(`Failed to take screenshot: ${response.status}`);
  }
  return response.json();
}

/**
 * Encoding Client
 * API client for encoding/export operations
 */

import type {
  EncodingOptions,
  EncodingProgress,
  StartEncodingRequest,
  StartEncodingResponse,
  EncodingCompleteResponse,
} from '../types';

const BACKEND_BASE_URL = 'http://localhost:5001';

/**
 * Start an encoding job
 */
export async function startEncoding(request: StartEncodingRequest): Promise<StartEncodingResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to start encoding: ${error}`);
  }
  return response.json();
}

/**
 * Cancel an encoding job
 */
export async function cancelEncoding(jobId: string): Promise<void> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/cancel`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jobId }),
  });
  if (!response.ok) {
    throw new Error(`Failed to cancel encoding: ${response.status}`);
  }
}

/**
 * Get encoding job progress
 */
export async function getEncodingProgress(jobId: string): Promise<EncodingProgress> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/progress/${jobId}`);
  if (!response.ok) {
    throw new Error(`Failed to get encoding progress: ${response.status}`);
  }
  return response.json();
}

/**
 * Get list of active encoding jobs
 */
export async function getActiveJobs(): Promise<EncodingProgress[]> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/jobs`);
  if (!response.ok) {
    throw new Error(`Failed to get active jobs: ${response.status}`);
  }
  return response.json();
}

/**
 * Get available encoders
 */
export async function getAvailableEncoders(): Promise<{
  gif: string[];
  video: string[];
  apng: string[];
  webp: string[];
}> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/encoders`);
  if (!response.ok) {
    throw new Error(`Failed to get available encoders: ${response.status}`);
  }
  return response.json();
}

/**
 * Validate encoding options before starting
 */
export async function validateEncodingOptions(
  options: EncodingOptions
): Promise<{ valid: boolean; errors: string[]; warnings: string[] }> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/validate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(options),
  });
  if (!response.ok) {
    throw new Error(`Failed to validate encoding options: ${response.status}`);
  }
  return response.json();
}

/**
 * Estimate output file size
 */
export async function estimateFileSize(
  projectId: string,
  options: EncodingOptions
): Promise<{ estimatedSize: number; confidence: 'low' | 'medium' | 'high' }> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/estimate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ projectId, options }),
  });
  if (!response.ok) {
    throw new Error(`Failed to estimate file size: ${response.status}`);
  }
  return response.json();
}

/**
 * Get encoding result after completion
 */
export async function getEncodingResult(jobId: string): Promise<EncodingCompleteResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/result/${jobId}`);
  if (!response.ok) {
    throw new Error(`Failed to get encoding result: ${response.status}`);
  }
  return response.json();
}

/**
 * Start batch encoding (multiple projects/outputs)
 */
export async function startBatchEncoding(
  requests: StartEncodingRequest[]
): Promise<{ jobIds: string[]; errors: { index: number; error: string }[] }> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/encoding/batch`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ requests }),
  });
  if (!response.ok) {
    throw new Error(`Failed to start batch encoding: ${response.status}`);
  }
  return response.json();
}

/**
 * Project Client
 * API client for project save/load operations
 */

import { invoke } from '@tauri-apps/api/core';
import type {
  Project,
  CreateProjectRequest,
  OpenProjectRequest,
  SaveProjectRequest,
  ProjectLoadResponse,
  ProjectSaveResponse,
  ProjectFileInfo,
  ImportMediaRequest,
  ImportMediaResponse,
} from '../types';

const BACKEND_BASE_URL = 'http://localhost:5001';

/**
 * Create a new project
 */
export async function createProject(request: CreateProjectRequest): Promise<Project> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/create`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to create project: ${error}`);
  }
  return response.json();
}

/**
 * Open a project file
 */
export async function openProject(request: OpenProjectRequest): Promise<ProjectLoadResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/open`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to open project: ${error}`);
  }
  return response.json();
}

/**
 * Save a project
 */
export async function saveProject(request: SaveProjectRequest): Promise<ProjectSaveResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/save`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to save project: ${error}`);
  }
  return response.json();
}

/**
 * Save project to a new location
 */
export async function saveProjectAs(
  projectId: string,
  path: string
): Promise<ProjectSaveResponse> {
  return saveProject({ projectId, path });
}

/**
 * Get project info without fully loading
 */
export async function getProjectInfo(path: string): Promise<ProjectFileInfo> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/info`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path }),
  });
  if (!response.ok) {
    throw new Error(`Failed to get project info: ${response.status}`);
  }
  return response.json();
}

/**
 * Get recent projects list
 */
export async function getRecentProjects(): Promise<ProjectFileInfo[]> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/recent`);
  if (!response.ok) {
    throw new Error(`Failed to get recent projects: ${response.status}`);
  }
  return response.json();
}

/**
 * Import media into project
 */
export async function importMedia(
  projectId: string,
  request: ImportMediaRequest
): Promise<ImportMediaResponse> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/${projectId}/import`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to import media: ${error}`);
  }
  return response.json();
}

/**
 * Export project frames to files
 */
export async function exportFrames(
  projectId: string,
  outputDir: string,
  format: 'png' | 'jpg' | 'bmp' = 'png'
): Promise<{ exportedCount: number; outputDirectory: string }> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/${projectId}/export-frames`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ outputDir, format }),
  });
  if (!response.ok) {
    throw new Error(`Failed to export frames: ${response.status}`);
  }
  return response.json();
}

/**
 * Show file open dialog via Tauri
 */
export async function showOpenDialog(filters?: { name: string; extensions: string[] }[]): Promise<string | null> {
  return invoke<string | null>('show_open_dialog', { filters });
}

/**
 * Show file save dialog via Tauri
 */
export async function showSaveDialog(
  defaultName?: string,
  filters?: { name: string; extensions: string[] }[]
): Promise<string | null> {
  return invoke<string | null>('show_save_dialog', { defaultName, filters });
}

/**
 * Show folder picker dialog via Tauri
 */
export async function showFolderDialog(): Promise<string | null> {
  return invoke<string | null>('show_folder_dialog');
}

/**
 * Clear auto-save data for a project
 */
export async function clearAutoSave(projectId: string): Promise<void> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/${projectId}/autosave`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    throw new Error(`Failed to clear auto-save: ${response.status}`);
  }
}

/**
 * Check if auto-save exists for a project
 */
export async function hasAutoSave(projectId: string): Promise<boolean> {
  const response = await fetch(`${BACKEND_BASE_URL}/api/project/${projectId}/autosave`);
  if (!response.ok) {
    throw new Error(`Failed to check auto-save: ${response.status}`);
  }
  const result = await response.json();
  return result.exists;
}

/**
 * Recover project from auto-save
 */
export async function recoverFromAutoSave(projectId: string): Promise<ProjectLoadResponse> {
