/**
 * WebSocket Manager
 * Centralized WebSocket connection management with reconnection logic
 */

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'reconnecting' | 'error';

export interface WebSocketMessage<T = unknown> {
  type: string;
  payload?: T;
  timestamp: string;
  correlationId?: string;
}

export interface WebSocketManagerOptions {
  url: string;
  reconnect?: boolean;
  reconnectInterval?: number;
  maxReconnectAttempts?: number;
  heartbeatInterval?: number;
  heartbeatTimeout?: number;
}

type MessageHandler<T = unknown> = (message: WebSocketMessage<T>) => void;
type StateChangeHandler = (state: ConnectionState) => void;
type ErrorHandler = (error: Error) => void;

const DEFAULT_OPTIONS: Required<Omit<WebSocketManagerOptions, 'url'>> = {
  reconnect: true,
  reconnectInterval: 3000,
  maxReconnectAttempts: 5,
  heartbeatInterval: 30000,
  heartbeatTimeout: 10000,
};

export class WebSocketManager {
  private socket: WebSocket | null = null;
  private options: Required<WebSocketManagerOptions>;
  private state: ConnectionState = 'disconnected';
  private reconnectAttempts = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  private heartbeatTimeoutTimer: ReturnType<typeof setTimeout> | null = null;
  private messageHandlers: Map<string, Set<MessageHandler>> = new Map();
  private stateChangeHandlers: Set<StateChangeHandler> = new Set();
  private errorHandlers: Set<ErrorHandler> = new Set();
  private pendingMessages: WebSocketMessage[] = [];
  private lastPong: number = 0;

  constructor(options: WebSocketManagerOptions) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  /**
   * Get current connection state
   */
  getState(): ConnectionState {
    return this.state;
  }

  /**
   * Check if connected
   */
  isConnected(): boolean {
    return this.state === 'connected' && this.socket?.readyState === WebSocket.OPEN;
  }

  /**
   * Connect to WebSocket server
   */
  connect(): void {
    if (this.state === 'connected' || this.state === 'connecting') {
      return;
    }

    this.setState('connecting');
    this.createSocket();
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect(): void {
    this.stopReconnect();
    this.stopHeartbeat();

    if (this.socket) {
      this.socket.onclose = null; // Prevent reconnect on intentional close
      this.socket.close(1000, 'Client disconnect');
      this.socket = null;
    }

    this.setState('disconnected');
  }

  /**
   * Send a message
   */
  send<T>(type: string, payload?: T, correlationId?: string): void {
    const message: WebSocketMessage<T> = {
      type,
      payload,
      timestamp: new Date().toISOString(),
      correlationId,
    };

    if (this.isConnected()) {
      this.socket!.send(JSON.stringify(message));
    } else {
      // Queue message for when connected
      this.pendingMessages.push(message as WebSocketMessage);
    }
  }

  /**
   * Subscribe to a specific message type
   */
  subscribe<T = unknown>(type: string, handler: MessageHandler<T>): () => void {
    if (!this.messageHandlers.has(type)) {
      this.messageHandlers.set(type, new Set());
    }
    this.messageHandlers.get(type)!.add(handler as MessageHandler);

    // Return unsubscribe function
    return () => {
      this.messageHandlers.get(type)?.delete(handler as MessageHandler);
    };
  }

  /**
   * Subscribe to all messages
   */
  subscribeAll(handler: MessageHandler): () => void {
    return this.subscribe('*', handler);
  }

  /**
   * Subscribe to state changes
   */
  onStateChange(handler: StateChangeHandler): () => void {
    this.stateChangeHandlers.add(handler);
    return () => {
      this.stateChangeHandlers.delete(handler);
    };
  }

  /**
   * Subscribe to errors
   */
  onError(handler: ErrorHandler): () => void {
    this.errorHandlers.add(handler);
    return () => {
      this.errorHandlers.delete(handler);
    };
  }

  /**
   * Send a request and wait for response
   */
  request<T, R>(type: string, payload?: T, timeout: number = 30000): Promise<R> {
    return new Promise((resolve, reject) => {
      const correlationId = crypto.randomUUID();
      const responseType = `${type}:response`;

      const timer = setTimeout(() => {
        unsubscribe();
        reject(new Error(`Request timeout for ${type}`));
      }, timeout);

      const unsubscribe = this.subscribe<R>(responseType, (message) => {
        if (message.correlationId === correlationId) {
          clearTimeout(timer);
          unsubscribe();
          resolve(message.payload as R);
        }
      });

      this.send(type, payload, correlationId);
    });
  }

  private createSocket(): void {
    try {
      this.socket = new WebSocket(this.options.url);

      this.socket.onopen = this.handleOpen.bind(this);
      this.socket.onclose = this.handleClose.bind(this);
      this.socket.onerror = this.handleError.bind(this);
      this.socket.onmessage = this.handleMessage.bind(this);
    } catch (error) {
      this.handleError(error as Event);
    }
  }

  private handleOpen(): void {
    this.setState('connected');
    this.reconnectAttempts = 0;
    this.startHeartbeat();
    this.flushPendingMessages();
  }

  private handleClose(event: CloseEvent): void {
    this.stopHeartbeat();

    if (event.wasClean) {
      this.setState('disconnected');
    } else if (this.options.reconnect && this.reconnectAttempts < this.options.maxReconnectAttempts) {
      this.scheduleReconnect();
    } else {
      this.setState('error');
    }
  }

  private handleError(event: Event): void {
    const error = new Error('WebSocket error');
    this.notifyError(error);

    if (this.state === 'connecting' && this.options.reconnect) {
      this.scheduleReconnect();
    }
  }

  private handleMessage(event: MessageEvent): void {
    try {
      const message = JSON.parse(event.data) as WebSocketMessage;

      // Handle pong for heartbeat
      if (message.type === 'pong') {
        this.lastPong = Date.now();
        this.clearHeartbeatTimeout();
        return;
      }

      // Notify specific handlers
      const handlers = this.messageHandlers.get(message.type);
      if (handlers) {
        handlers.forEach((handler) => handler(message));
      }

      // Notify wildcard handlers
      const wildcardHandlers = this.messageHandlers.get('*');
      if (wildcardHandlers) {
        wildcardHandlers.forEach((handler) => handler(message));
      }
    } catch (error) {
      console.error('Failed to parse WebSocket message:', error);
    }
  }

  private setState(state: ConnectionState): void {
    if (this.state !== state) {
      this.state = state;
      this.stateChangeHandlers.forEach((handler) => handler(state));
    }
  }

  private notifyError(error: Error): void {
    this.errorHandlers.forEach((handler) => handler(error));
  }

  private scheduleReconnect(): void {
    this.setState('reconnecting');
    this.reconnectAttempts++;

    this.reconnectTimer = setTimeout(() => {
      this.createSocket();
    }, this.options.reconnectInterval);
  }

  private stopReconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.reconnectAttempts = 0;
  }

  private startHeartbeat(): void {
    this.lastPong = Date.now();

    this.heartbeatTimer = setInterval(() => {
      if (this.isConnected()) {
        this.send('ping');
        this.setHeartbeatTimeout();
      }
    }, this.options.heartbeatInterval);
  }

  private stopHeartbeat(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
    this.clearHeartbeatTimeout();
  }

  private setHeartbeatTimeout(): void {
    this.heartbeatTimeoutTimer = setTimeout(() => {
      console.warn('Heartbeat timeout - reconnecting');
      this.socket?.close();
    }, this.options.heartbeatTimeout);
  }

  private clearHeartbeatTimeout(): void {
    if (this.heartbeatTimeoutTimer) {
      clearTimeout(this.heartbeatTimeoutTimer);
      this.heartbeatTimeoutTimer = null;
    }
  }

  private flushPendingMessages(): void {
    while (this.pendingMessages.length > 0 && this.isConnected()) {
      const message = this.pendingMessages.shift()!;
      this.socket!.send(JSON.stringify(message));
    }
  }
}

// Singleton instance for the main backend connection
let mainConnection: WebSocketManager | null = null;

/**
 * Get or create the main WebSocket connection
 */
export function getWebSocketManager(url: string = 'ws://localhost:5001/ws'): WebSocketManager {
  if (!mainConnection) {
    mainConnection = new WebSocketManager({ url });
  }
  return mainConnection;
}

/**
 * Destroy the main WebSocket connection
 */
export function destroyWebSocketManager(): void {
  if (mainConnection) {
    mainConnection.disconnect();
    mainConnection = null;
  }
}

/**
 * Frame Stream
 * Real-time frame data streaming during capture
 */

import { getWebSocketManager, type WebSocketMessage } from './WebSocketManager';

/** Frame data received from WebSocket */
export interface StreamedFrame {
  index: number;
  timestamp: number;
  imageData: string; // Base64 encoded
  width: number;
  height: number;
  delay: number;
  cursorX?: number;
  cursorY?: number;
  mouseClicked?: boolean;
}

/** Frame stream event types */
export type FrameStreamEvent =
  | { type: 'frame'; frame: StreamedFrame }
  | { type: 'started'; sessionId: string }
  | { type: 'paused' }
  | { type: 'resumed' }
  | { type: 'stopped'; totalFrames: number }
  | { type: 'error'; error: string };

type FrameStreamHandler = (event: FrameStreamEvent) => void;

class FrameStreamManager {
  private handlers: Set<FrameStreamHandler> = new Set();
  private unsubscribers: (() => void)[] = [];
  private isActive = false;
  private sessionId: string | null = null;
  private frameBuffer: StreamedFrame[] = [];
  private maxBufferSize = 10;
  private lastFrameIndex = -1;

  /**
   * Start listening to frame stream
   */
  start(sessionId: string): void {
    if (this.isActive) {
      return;
    }

    this.sessionId = sessionId;
    this.isActive = true;
    this.frameBuffer = [];
    this.lastFrameIndex = -1;

    const ws = getWebSocketManager();

    // Subscribe to frame messages
    const unsubFrame = ws.subscribe<StreamedFrame>('capture:frame', (message) => {
      this.handleFrame(message.payload!);
    });

    const unsubStarted = ws.subscribe<{ sessionId: string }>('capture:started', (message) => {
      this.emit({ type: 'started', sessionId: message.payload!.sessionId });
    });

    const unsubPaused = ws.subscribe('capture:paused', () => {
      this.emit({ type: 'paused' });
    });

    const unsubResumed = ws.subscribe('capture:resumed', () => {
      this.emit({ type: 'resumed' });
    });

    const unsubStopped = ws.subscribe<{ totalFrames: number }>('capture:stopped', (message) => {
      this.emit({ type: 'stopped', totalFrames: message.payload!.totalFrames });
    });

    const unsubError = ws.subscribe<{ error: string }>('capture:error', (message) => {
      this.emit({ type: 'error', error: message.payload!.error });
    });

    this.unsubscribers = [
      unsubFrame,
      unsubStarted,
      unsubPaused,
      unsubResumed,
      unsubStopped,
      unsubError,
    ];

    // Request to start receiving frames
    ws.send('capture:subscribe', { sessionId });
  }

  /**
   * Stop listening to frame stream
   */
  stop(): void {
    if (!this.isActive) {
      return;
    }

    // Unsubscribe from all messages
    this.unsubscribers.forEach((unsub) => unsub());
    this.unsubscribers = [];

    // Tell server to stop sending frames
    const ws = getWebSocketManager();
    ws.send('capture:unsubscribe', { sessionId: this.sessionId });

    this.isActive = false;
    this.sessionId = null;
    this.frameBuffer = [];
  }

  /**
   * Subscribe to frame stream events
   */
  subscribe(handler: FrameStreamHandler): () => void {
    this.handlers.add(handler);
    return () => {
      this.handlers.delete(handler);
    };
  }

  /**
   * Get buffered frames
   */
  getBufferedFrames(): StreamedFrame[] {
    return [...this.frameBuffer];
  }

  /**
   * Clear frame buffer
   */
  clearBuffer(): void {
    this.frameBuffer = [];
  }

  /**
   * Check if stream is active
   */
  isStreaming(): boolean {
    return this.isActive;
  }

  /**
   * Get current session ID
   */
  getSessionId(): string | null {
    return this.sessionId;
  }

  /**
   * Get last received frame index
   */
  getLastFrameIndex(): number {
    return this.lastFrameIndex;
  }

  private handleFrame(frame: StreamedFrame): void {
    // Check for out-of-order frames
    if (frame.index <= this.lastFrameIndex) {
      console.warn(`Out of order frame received: ${frame.index}, expected > ${this.lastFrameIndex}`);
      return;
    }

    // Check for dropped frames
    if (frame.index > this.lastFrameIndex + 1) {
      console.warn(`Dropped frames detected: ${this.lastFrameIndex + 1} - ${frame.index - 1}`);
    }

    this.lastFrameIndex = frame.index;

    // Add to buffer
    this.frameBuffer.push(frame);
    if (this.frameBuffer.length > this.maxBufferSize) {
      this.frameBuffer.shift();
    }

    // Emit event
    this.emit({ type: 'frame', frame });
  }

  private emit(event: FrameStreamEvent): void {
    this.handlers.forEach((handler) => {
      try {
        handler(event);
      } catch (error) {
        console.error('Frame stream handler error:', error);
      }
    });
  }
}

// Singleton instance
let instance: FrameStreamManager | null = null;

/**
 * Get frame stream manager instance
 */
export function getFrameStream(): FrameStreamManager {
  if (!instance) {
    instance = new FrameStreamManager();
  }
  return instance;
}

/**
 * React hook-friendly subscription
 */
export function subscribeToFrameStream(
  sessionId: string,
  handler: FrameStreamHandler
): () => void {
  const stream = getFrameStream();
  stream.start(sessionId);
  const unsubscribe = stream.subscribe(handler);

  return () => {
    unsubscribe();
    // Only stop if no more handlers
    if (stream['handlers'].size === 0) {
      stream.stop();
    }
  };
}

/**
 * Progress Stream
 * Real-time encoding/processing progress updates
 */

import { getWebSocketManager } from './WebSocketManager';
import type { EncodingProgress, UploadProgress } from '../types';

/** Progress stream event types */
export type ProgressStreamEvent =
  | { type: 'encoding:progress'; progress: EncodingProgress }
  | { type: 'encoding:started'; jobId: string }
  | { type: 'encoding:completed'; jobId: string; outputPath: string; fileSize: number }
  | { type: 'encoding:failed'; jobId: string; error: string }
  | { type: 'encoding:cancelled'; jobId: string }
  | { type: 'upload:progress'; progress: UploadProgress }
  | { type: 'upload:completed'; uploadId: string; url: string }
  | { type: 'upload:failed'; uploadId: string; error: string }
  | { type: 'processing:progress'; operationId: string; progress: number; stage: string }
  | { type: 'processing:completed'; operationId: string }
  | { type: 'processing:failed'; operationId: string; error: string };

type ProgressStreamHandler = (event: ProgressStreamEvent) => void;

class ProgressStreamManager {
  private handlers: Set<ProgressStreamHandler> = new Set();
  private jobHandlers: Map<string, Set<ProgressStreamHandler>> = new Map();
  private unsubscribers: (() => void)[] = [];
  private isSubscribed = false;

  /**
   * Subscribe to all progress events
   */
  subscribeAll(handler: ProgressStreamHandler): () => void {
    this.handlers.add(handler);
    this.ensureSubscribed();

    return () => {
      this.handlers.delete(handler);
      this.checkUnsubscribe();
    };
  }

  /**
   * Subscribe to a specific job's progress
   */
  subscribeToJob(jobId: string, handler: ProgressStreamHandler): () => void {
    if (!this.jobHandlers.has(jobId)) {
      this.jobHandlers.set(jobId, new Set());
    }
    this.jobHandlers.get(jobId)!.add(handler);
    this.ensureSubscribed();

    // Tell server to send updates for this job
    const ws = getWebSocketManager();
    ws.send('progress:subscribe', { jobId });

    return () => {
      this.jobHandlers.get(jobId)?.delete(handler);
      if (this.jobHandlers.get(jobId)?.size === 0) {
        this.jobHandlers.delete(jobId);
        ws.send('progress:unsubscribe', { jobId });
      }
      this.checkUnsubscribe();
    };
  }

  /**
   * Subscribe to encoding progress for a job
   */
  subscribeToEncoding(jobId: string, handler: (progress: EncodingProgress) => void): () => void {
    return this.subscribeToJob(jobId, (event) => {
      if (event.type === 'encoding:progress' && event.progress.jobId === jobId) {
        handler(event.progress);
      }
    });
  }

  /**
   * Subscribe to upload progress
   */
  subscribeToUpload(uploadId: string, handler: (progress: UploadProgress) => void): () => void {
    return this.subscribeToJob(uploadId, (event) => {
      if (event.type === 'upload:progress' && event.progress.uploadId === uploadId) {
        handler(event.progress);
      }
    });
  }

  private ensureSubscribed(): void {
    if (this.isSubscribed) {
      return;
    }

    const ws = getWebSocketManager();

    // Encoding progress
    const unsubEncodingProgress = ws.subscribe<EncodingProgress>('encoding:progress', (message) => {
      this.emit({ type: 'encoding:progress', progress: message.payload! });
    });

    const unsubEncodingStarted = ws.subscribe<{ jobId: string }>('encoding:started', (message) => {
      this.emit({ type: 'encoding:started', jobId: message.payload!.jobId });
    });

    const unsubEncodingCompleted = ws.subscribe<{ jobId: string; outputPath: string; fileSize: number }>(
      'encoding:completed',
      (message) => {
        this.emit({
          type: 'encoding:completed',
          jobId: message.payload!.jobId,
          outputPath: message.payload!.outputPath,
          fileSize: message.payload!.fileSize,
        });
      }
    );

    const unsubEncodingFailed = ws.subscribe<{ jobId: string; error: string }>(
      'encoding:failed',
      (message) => {
        this.emit({
          type: 'encoding:failed',
          jobId: message.payload!.jobId,
          error: message.payload!.error,
        });
      }
    );

    const unsubEncodingCancelled = ws.subscribe<{ jobId: string }>('encoding:cancelled', (message) => {
      this.emit({ type: 'encoding:cancelled', jobId: message.payload!.jobId });
    });

    // Upload progress
    const unsubUploadProgress = ws.subscribe<UploadProgress>('upload:progress', (message) => {
      this.emit({ type: 'upload:progress', progress: message.payload! });
    });

    const unsubUploadCompleted = ws.subscribe<{ uploadId: string; url: string }>(
      'upload:completed',
      (message) => {
        this.emit({
          type: 'upload:completed',
          uploadId: message.payload!.uploadId,
          url: message.payload!.url,
        });
      }
    );

    const unsubUploadFailed = ws.subscribe<{ uploadId: string; error: string }>(
      'upload:failed',
      (message) => {
        this.emit({
          type: 'upload:failed',
          uploadId: message.payload!.uploadId,
          error: message.payload!.error,
        });
      }
    );

    // Processing progress
    const unsubProcessingProgress = ws.subscribe<{ operationId: string; progress: number; stage: string }>(
      'processing:progress',
      (message) => {
        this.emit({
          type: 'processing:progress',
          operationId: message.payload!.operationId,
          progress: message.payload!.progress,
          stage: message.payload!.stage,
        });
      }
    );

    const unsubProcessingCompleted = ws.subscribe<{ operationId: string }>(
      'processing:completed',
      (message) => {
        this.emit({ type: 'processing:completed', operationId: message.payload!.operationId });
      }
    );

    const unsubProcessingFailed = ws.subscribe<{ operationId: string; error: string }>(
      'processing:failed',
      (message) => {
        this.emit({
          type: 'processing:failed',
          operationId: message.payload!.operationId,
          error: message.payload!.error,
        });
      }
    );

    this.unsubscribers = [
      unsubEncodingProgress,
      unsubEncodingStarted,
      unsubEncodingCompleted,
      unsubEncodingFailed,
      unsubEncodingCancelled,
      unsubUploadProgress,
      unsubUploadCompleted,
      unsubUploadFailed,
      unsubProcessingProgress,
      unsubProcessingCompleted,
      unsubProcessingFailed,
    ];

    this.isSubscribed = true;
  }

  private checkUnsubscribe(): void {
    if (this.handlers.size === 0 && this.jobHandlers.size === 0) {
      this.unsubscribers.forEach((unsub) => unsub());
      this.unsubscribers = [];
      this.isSubscribed = false;
    }
  }

  private emit(event: ProgressStreamEvent): void {
    // Notify global handlers
    this.handlers.forEach((handler) => {
      try {
        handler(event);
      } catch (error) {
        console.error('Progress stream handler error:', error);
      }
    });

    // Notify job-specific handlers
    const jobId = this.getJobIdFromEvent(event);
    if (jobId) {
      const jobHandlers = this.jobHandlers.get(jobId);
      if (jobHandlers) {
        jobHandlers.forEach((handler) => {
          try {
            handler(event);
          } catch (error) {
            console.error('Progress stream handler error:', error);
          }
        });
      }
    }
  }

  private getJobIdFromEvent(event: ProgressStreamEvent): string | null {
    switch (event.type) {
      case 'encoding:progress':
        return event.progress.jobId;
      case 'encoding:started':
      case 'encoding:completed':
      case 'encoding:failed':
      case 'encoding:cancelled':
        return event.jobId;
      case 'upload:progress':
        return event.progress.uploadId;
      case 'upload:completed':
      case 'upload:failed':
        return event.uploadId;
      case 'processing:progress':
      case 'processing:completed':
      case 'processing:failed':
        return event.operationId;
      default:
        return null;
    }
  }
}

// Singleton instance
let instance: ProgressStreamManager | null = null;

/**
 * Get progress stream manager instance
 */
export function getProgressStream(): ProgressStreamManager {
  if (!instance) {
    instance = new ProgressStreamManager();
  }
  return instance;
}

/**
 * Subscribe to all progress events
 */
export function subscribeToProgress(handler: ProgressStreamHandler): () => void {
  return getProgressStream().subscribeAll(handler);
}

/**
 * Subscribe to encoding progress for a specific job
 */
export function subscribeToEncodingProgress(
  jobId: string,
  handler: (progress: EncodingProgress) => void
): () => void {
  return getProgressStream().subscribeToEncoding(jobId, handler);
}

/**
 * Subscribe to upload progress for a specific upload
 */
export function subscribeToUploadProgress(
  uploadId: string,
  handler: (progress: UploadProgress) => void
): () => void {
  return getProgressStream().subscribeToUpload(uploadId, handler);
}

/**
 * WebSocket Layer Index
 * Re-exports WebSocket management utilities
 */

// WebSocket Manager
export {
  WebSocketManager,
  getWebSocketManager,
  destroyWebSocketManager,
} from './WebSocketManager';
export type {
  ConnectionState,
  WebSocketMessage,
  WebSocketManagerOptions,
} from './WebSocketManager';

// Frame Stream
export {
  getFrameStream,
  subscribeToFrameStream,
} from './frameStream';
export type {
  StreamedFrame,
  FrameStreamEvent,
} from './frameStream';

// Progress Stream
export {
  getProgressStream,
  subscribeToProgress,
  subscribeToEncodingProgress,
  subscribeToUploadProgress,
} from './progressStream';
export type { ProgressStreamEvent } from './progressStream';

